const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');
const clamp=(n,a=0,b=1)=>Math.max(a,Math.min(b,n));
const header=$('#header');
// Navigation. Every destination leads to a real section or an explicitly labeled preview.
function closeMenus(){ $$('.nav-trigger').forEach(b=>{b.setAttribute('aria-expanded','false');$('#'+b.getAttribute('aria-controls')).hidden=true;}); }
$$('.nav-trigger').forEach(b=>b.addEventListener('click',()=>{const open=b.getAttribute('aria-expanded')!=='true';closeMenus();b.setAttribute('aria-expanded',String(open));$('#'+b.getAttribute('aria-controls')).hidden=!open;}));
$$('.nav-item').forEach(item=>{let timer;item.addEventListener('pointerenter',e=>{if(e.pointerType==='touch')return;clearTimeout(timer);closeMenus();const b=$('button',item);b.setAttribute('aria-expanded','true');$('.nav-dropdown',item).hidden=false;});item.addEventListener('pointerleave',()=>{timer=setTimeout(closeMenus,140);});});
document.addEventListener('click',e=>{if(!e.target.closest('.nav-item'))closeMenus();});
const mobileToggle=$('.mobile-toggle'),mobileMenu=$('#mobile-menu');
function closeMobile(){mobileMenu.hidden=true;mobileToggle.setAttribute('aria-expanded','false');mobileToggle.setAttribute('aria-label','Open menu');}
mobileToggle.addEventListener('click',()=>{const open=mobileMenu.hidden;mobileMenu.hidden=!open;mobileToggle.setAttribute('aria-expanded',String(open));mobileToggle.setAttribute('aria-label',open?'Close menu':'Open menu');});
$$('a[href^="#"]').forEach(a=>a.addEventListener('click',()=>{closeMenus();closeMobile();}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenus();closeMobile();}});

// Original Chancery pavilion: a pinned, scroll-directed camera move into live HTML.
const hero=$('.hero');const stage=document.createElement('div');stage.className='hero-stage';while(hero.firstChild)stage.append(hero.firstChild);hero.append(stage);
const camera=document.createElement('div');camera.className='hero-camera';camera.setAttribute('aria-hidden','true');
const landscape=document.createElement('img');landscape.className='pavilion-image';landscape.src='assets/chancery-pavilion.png';landscape.alt='';landscape.fetchPriority='high';camera.append(landscape);
const screen=document.createElement('div');screen.className='pavilion-screen';screen.setAttribute('aria-hidden','true');const screenContent=document.createElement('div');screenContent.className='screen-content';const screenWindow=$('.app-window').cloneNode(true);screenWindow.style.cssText='transform:none;width:960px;height:584px;border:0;border-radius:0;grid-template-columns:180px 1fr;box-shadow:none';screenContent.append(screenWindow);screen.append(screenContent);stage.prepend(camera);stage.append(screen);
const aiDashboard=`<div class="ai-toolbar"><span>Workspace</span><span class="status-dot">Private lane</span><span class="ai-search">Search your office &nbsp; ⌘ K</span></div><div class="ai-greeting"><img src="assets/mark.svg" alt=""><small>YOUR PRIVATE BACK OFFICE</small><h3>What are we working on?</h3><p>A fresh perspective. A little help. A place to start.</p></div><div class="ai-prompt"><div class="ai-prompt-text">Ask a question, explore an idea, or put a clerk to work<span class="ai-caret"></span></div><div class="ai-prompt-controls"><span class="ai-plus">+</span><span class="ai-model">✳ &nbsp; Auto · Best model for the task &nbsp;⌄</span><span class="ai-private">⌑ &nbsp; Private</span><span class="ai-send">↑</span></div></div><div class="ai-suggestions"><span>◈ &nbsp; Compare models</span><span>▤ &nbsp; Research a topic</span><span>✳ &nbsp; Ask a clerk</span></div><div class="ai-bottom"><div><span class="ai-section-label">YOUR ROOMS <b>View all ↗</b></span><p>◇ &nbsp; Protocol research <small>5 members</small></p><p>◇ &nbsp; Treasury & operations <small>8 members</small></p><p>◇ &nbsp; The next chapter <small>4 members</small></p></div><div><span class="ai-section-label">WORKING ALONGSIDE YOU</span><p>✳ &nbsp; Treasury Clerk <i class="green-dot"></i></p><small class="ai-task">Monthly report ready for review</small><div class="ai-report">▤ &nbsp; November summary <span>Review ↗</span></div></div></div>`;
$('.app-main',screenWindow).innerHTML=aiDashboard;
$$('.sidebar-link',screenWindow).forEach((e,i)=>e.classList.toggle('selected',i===1));
$('.app-main',$('#product-visual')).innerHTML=aiDashboard;
const light=$('.light-content'),finale=$('.dark-finale');let scheduled=false;
function updateScroll(){scheduled=false;const y=window.scrollY,h=innerHeight;const progress=clamp(y/Math.max(1,hero.offsetHeight-stage.offsetHeight));const vw=stage.clientWidth,vh=stage.clientHeight;const base=Math.max(vw/1672,vh/941);const x0=(vw-1672*base)/2,y0=(vh-941*base)/2;const initialX=836*base+x0,initialY=609*base+y0;const targetWidth=Math.min(vw*.88,vh*.78*(300/182));const targetZoom=targetWidth/(300*base);const move=reducedMotion.matches?0:clamp(progress/.87);const eased=move*move*(3-2*move);const zoom=1+(targetZoom-1)*eased;const cx=initialX+(vw/2-initialX)*eased,cy=initialY+(vh*.53-initialY)*eased;const scale=base*zoom;const tx=cx-836*scale,ty=cy-609*scale;camera.style.transform=`translate(${tx}px,${ty}px) scale(${scale})`;screen.style.left=(tx+686*scale)+'px';screen.style.top=(ty+518*scale)+'px';screen.style.width=(300*scale)+'px';screen.style.height=(182.5*scale)+'px';screenContent.style.transform=`scale(${300*scale/960})`;
if(!reducedMotion.matches){const textOpacity=1-clamp((progress-.12)/.23);$('.hero-content').style.opacity=textOpacity;$('.hero-content').style.filter=`blur(${(1-textOpacity)*5}px)`;$('.hero-content').style.pointerEvents=textOpacity<.1?'none':'';$('.hero-note').style.opacity=1-clamp(progress/.3);$('.scroll-cue').style.opacity=1-clamp(progress/.15);// Hold the final camera frame; sticky positioning releases it into normal page scrolling.
}
const lightY=light.getBoundingClientRect().top,lightEnd=finale.getBoundingClientRect().top;const palette=reducedMotion.matches?1:clamp((h*.95-lightY)/(h*.8))*(1-clamp((h*.6-lightEnd)/(h*.6)));light.style.setProperty('--theme-progress',palette.toFixed(3));header.classList.toggle('scrolled',y>40);header.classList.toggle('light',lightY<72&&lightEnd>72);}
window.addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(updateScroll);}},{passive:true});window.addEventListener('resize',updateScroll);reducedMotion.addEventListener('change',()=>{if(reducedMotion.matches){$('.hero-content').style.opacity='1';$('.hero-content').style.filter='none';$('.hero-note').style.opacity='1';}updateScroll();});updateScroll();

// Product accordions use the reference's softened 400ms transition.
const originalApp=$('.app-main',$('#product-visual')).innerHTML;
const productPanels=[originalApp,
 `<div class="app-toolbar"><span>Rooms</span><span class="status-dot">End-to-end encrypted</span></div><div class="app-greeting"><small>YOUR TEAM'S SHARED SPACES</small><h3>A room for the work that matters.</h3></div><div class="app-two"><div class="mini-panel"><span>◇ PRIVATE ROOM</span><p style="font-size:17px;margin:24px 0">Treasury & operations</p><p>8 members · Members only</p></div><div class="mini-panel"><span>◇ PRIVATE ROOM</span><p style="font-size:17px;margin:24px 0">Protocol research</p><p>5 members · Private lane</p></div></div><div class="purse-summary" style="margin-top:24px"><span>The next chapter</span><strong style="font-size:23px">Let's make space for the next idea.</strong><div class="app-recent"><div><i>AL</i><p>The proposal is ready for everyone to review.<small>Today, 10:42 · Encrypted for this room</small></p></div><div><i>JM</i><p>Added the research notes and the revised draft.<small>Today, 10:46 · Encrypted for this room</small></p></div></div></div>`,
 `<div class="app-toolbar"><span>Clerks</span><span class="status-dot">Within approved limits</span></div><div class="app-greeting"><small>A JOB. A RULEBOOK. AN ALLOWANCE.</small><h3>Your office, working alongside you.</h3></div><div class="purse-summary"><span>✳ Treasury Clerk</span><strong style="font-size:24px">Monthly report ready for review</strong><div class="budget-label"><span>Monthly usage · 42.18 USDG</span><span>Limit · 150 USDG</span></div><div class="budget-line" style="margin-top:14px"><span style="width:28%"></span></div></div><div class="app-two"><div class="mini-panel"><span>✳ RESEARCH CLERK</span><p style="font-size:15px;margin-top:22px">Watching for changes</p><p>12 sources · Last checked 8 min ago</p></div><div class="mini-panel"><span>✳ GOVERNANCE CLERK</span><p style="font-size:15px;margin-top:22px">3 proposals summarized</p><p>Drafts ready · Owners sign</p></div></div><div class="app-recent"><span>Office rulebook</span><div><i>✓</i><p>Ask first above the per-task limit<small>Allowed tools and domains are enforced</small></p></div></div>`,
 `<div class="app-toolbar"><span>Ledger</span><span class="status-dot">Signed & verifiable</span></div><div class="app-greeting"><small>NOVEMBER 2026</small><h3>A clear record of every cent.</h3></div><div class="purse-summary"><span>Office usage this month</span><strong>384<span>.72 USDG</span></strong><div class="budget-label"><span>8 seats · 3 clerks · 4 rooms</span><span>Export statement ↗</span></div></div><div class="app-recent"><span>Latest receipts</span><div><i>✓</i><p>Workspace seats<small>8 members · Signed receipt</small></p><time>72.00 USDG</time></div><div><i>✓</i><p>Model & tool usage<small>Workspace · Signed receipt</small></p><time>270.54 USDG</time></div><div><i>✓</i><p>Treasury Clerk<small>Monthly reporting · Signed receipt</small></p><time>42.18 USDG</time></div></div><div class="mini-panel" style="margin-top:24px"><span>RECEIPT ROOT</span><p>0x7b4a…e29f &nbsp; · &nbsp; Settlement log root matches ✓</p></div>`];
let productSwap=0;
$$('[data-accordion]').forEach(group=>$$('.accordion-item h3 button',group).forEach(button=>button.addEventListener('click',()=>{if(button.getAttribute('aria-expanded')==='true')return;$$('.accordion-item',group).forEach(item=>{const b=$('h3 button',item),active=b===button;item.classList.toggle('active',active);b.setAttribute('aria-expanded',String(active));$('.accordion-body',item).hidden=!active;});const i=Number(button.dataset.index);if(group.dataset.accordion==='product'){clearTimeout(productSwap);const visual=$('#product-visual');visual.classList.add('switching');productSwap=setTimeout(()=>{$('.app-main',visual).innerHTML=productPanels[i];$$('.sidebar-link',visual).forEach((b,n)=>b.classList.toggle('selected',n===[0,2,3,4][i]));visual.classList.remove('switching');},reducedMotion.matches?0:200);}if(group.dataset.accordion==='setup')$('#setup-art-label').textContent=['ONE SAFE. ONE OFFICE.','YOUR PEOPLE. THEIR KEYS.','THE TEAM WORKS. THE LEDGER KEEPS.'][i];})));
const stories=[['FOR DAOS & PROTOCOLS','Big decisions deserve<br>a room of their own.','Research the proposal. Debate the details. Draft the vote. Keep your team’s thinking together, with a clear record of what was decided.'],['FOR FUNDS & COLLECTIVES','Good research needs<br>a little breathing room.','Compare perspectives, follow the details, and keep the discussion close. Give every deal its own space, with the right people in the room.'],['FOR INDEPENDENT STUDIOS','A shared ambition.<br>A space to make it happen.','Bring your collaborators, your tools, and your next big idea together. Give routine work to your clerks, and get back to the work that’s yours.']];
function setStory(i){const [label,title,body]=stories[i];$('#story-label').textContent=label;$('#story-title').innerHTML=title;$('#story-body').textContent=body;$$('[data-story]').forEach(b=>b.setAttribute('aria-selected',String(Number(b.dataset.story)===i)));if(!reducedMotion.matches)$('.story-copy').animate([{opacity:.2,transform:'translateY(5px)'},{opacity:1,transform:'translateY(0)'}],{duration:400,easing:'ease-out'});}
$$('[data-story]').forEach(b=>{b.addEventListener('click',()=>setStory(Number(b.dataset.story)));b.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const i=(Number(b.dataset.story)+(e.key==='ArrowRight'?1:2))%3;setStory(i);$(`[data-story="${i}"]`).focus();}});});$$('[data-team]').forEach(a=>a.addEventListener('click',()=>setStory(Number(a.dataset.team))));
const motionObserver=new IntersectionObserver(entries=>entries.forEach(e=>e.target.classList.toggle('motion-running',e.isIntersecting)),{threshold:.1});$$('.feature-art,.story-art,.office-visual,.split-section,.operations-section,.security-section').forEach(el=>motionObserver.observe(el));
// Editorial detail sheets.
const details={
 rooms:['THE ROOMS','A shared space. A private conversation.',`<p>A Room is an end-to-end encrypted space for a project: a deal, a launch, or an incident. Its key is wrapped to each member’s device keys, so Chancery stores ciphertext.</p><ul><li>Set room history to expire.</li><li>Rotate the room key when a member leaves.</li><li>Give guests time-limited access to a single room.</li><li>Pin a room to private lanes when the work calls for it.</li></ul><p>Encryption protects stored history. A compromised member device can still expose content that member can read.</p>`],
 clerks:['THE CLERKS','A job. A rulebook. An allowance.',`<p>A clerk is an AI agent with a defined job and limits. Treasury clerks draft reports, governance clerks summarize proposals, and research clerks watch the sources your team cares about.</p><ul><li>Choose allowed models, tools, and domains.</li><li>Set per-task and monthly caps.</li><li>Require approval above your ask-first threshold.</li><li>Pause a clerk when you need to.</li></ul><p>Clerks never hold signing power. They can draft a transaction; Safe owners review and sign.</p>`],
 ledger:['THE LEDGER','A signed receipt for every cent.',`<p>Every spend records the model, provider, lane, cost, and the seat or clerk that used it. The ledger ties work to usage and usage to a signed receipt.</p><p>Month-end statements organize that detail by seat, clerk, and room. Export CSV or JSON for your treasury’s records and share a verifiable statement with the people you choose.</p><p>The interactive demo includes an example CSV export using sample data.</p>`],
 pricing:['CLEAR FROM THE START','One seat. The whole workspace.',`<table><tbody><tr><td>Workspace seat</td><td>9 USDG / month</td></tr><tr><td>Model and tool usage</td><td>At cost + 5%</td></tr><tr><td>Additional per-clerk fee</td><td>None</td></tr><tr><td>Set or change an allowance</td><td>Network gas only</td></tr></tbody></table><p>Seat pricing includes the workspace, rooms, and guards. Usage settles daily from the allowance approved by your Safe. The Purse is a spending allowance; Chancery does not take custody of the team’s funds.</p><p>These are the indicative rates in the supplied product overview, dated October 3, 2026. This preview does not offer a live subscription or collect payment.</p>`],
 security:['THE SECURITY MODEL','Clear protections. Honest limits.',`<p>Rooms use device-bound encryption keys. Browser-side guards check for secrets before sending. Clerk budgets are bounded by allowances, and owners retain signing authority.</p><ul><li>Room encryption protects stored history, not a compromised member device.</li><li>Sealed mode depends on the enclave provider’s attestation and its physical security limits.</li><li>On ordinary model lanes, the provider processes the content. Zero-retention policy is distinct from encryption.</li><li>A spending cap limits cost, not judgment. Review thresholds still matter.</li><li>The supplied overview says no human audit has been completed yet.</li></ul>`],
 privacy:['PREVIEW PRIVACY','Take a look around. Leave nothing behind.',`<p>This website does not collect email addresses, connect wallets, or use analytics. The interactive office contains illustrative data only.</p><p>Demo changes live in this page’s memory and reset when you reload. A CSV export is generated in your browser and saved to your device. It is not sent to a server.</p><p>The private hosting service may process requests and authentication according to its own policies.</p>`],
 about:['ABOUT THIS PREVIEW','Chancery, the private back office.',`<p>A Chancery product preview with an original pavilion, a scroll-directed camera move, and an interactive workspace.</p><p>The sample workspace illustrates the product. Account creation, model execution, wallet connections, and settlement require the Chancery application.</p>`]
};
const detailDialog=$('#detail-dialog'),demoDialog=$('#demo-dialog');
function openDetail(key){const d=details[key];if(!d)return;$('#detail-label').textContent=d[0];$('#detail-title').textContent=d[1];$('#detail-body').innerHTML=d[2];detailDialog.showModal();document.body.style.overflow='hidden';}
$$('[data-details]').forEach(b=>b.addEventListener('click',()=>openDetail(b.dataset.details)));
$$('dialog').forEach(d=>{$('.dialog-close',d).addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});d.addEventListener('close',()=>{if(!$$('dialog[open]').length)document.body.style.overflow='';});});
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),4000);}
