 if(view==='Overview')el.innerHTML=`<div class="demo-summary"><div class="demo-card"><small>Monthly allowance</small><strong>2,000<span>.00 USDG</span></strong><div class="demo-progress"><i></i></div><div class="demo-budget-label"><span>384.72 used</span><span>1,615.28 available</span></div></div><div class="demo-card"><small>Your office</small><strong>8<span>members</span></strong><button class="underlined" data-route="Rooms">4 private rooms &nbsp; ↗</button></div></div><div class="demo-section-title"><span>Recent activity</span><button data-route="Ledger">View ledger ↗</button></div><div class="demo-activity"><div class="demo-activity-row"><i>✳</i><div>Treasury report ${reviewed?'reviewed':'ready for review'}<small>Treasury Clerk · November statement</small></div><time>12 min ago</time></div><div class="demo-activity-row"><i>◇</i><div>Protocol research room updated<small>New research notes · 5 members</small></div><time>38 min ago</time></div><div class="demo-activity-row"><i>✓</i><div>Daily usage receipt signed<small>Receipt root matches settlement log</small></div><time>1 hour ago</time></div></div>`;
